// The loupe. One photograph, one engine.
//
// Every view of the movement on this page — the hero, the six stops of the power
// path, the four layers — is the same file, framed differently. `applyView` is
// the only thing that ever moves it: give it a box, an <img> inside that box,
// and a region of the image, and it puts that region in the middle of the box.
//
// Regions are fractions of the image, so they survive any resize and any
// derivative. The image's own aspect ratio is the only measurement it needs.

export const PLATE_RATIO = 4000 / 3647

export function applyView(img, box, view, ratio = PLATE_RATIO) {
  if (!img || !box) return
  const bw = box.clientWidth
  const bh = box.clientHeight
  if (!bw || !bh) return

  // The region must be wide enough that the scaled image still covers the box.
  const maxW = bw / (ratio * bh)
  const w = Math.min(view.w, maxW, 1)
  const s = 1 / w

  const ih = bw / ratio // the img is laid out at 100% of the box width
  let x = bw / 2 - s * (view.cx * bw)
  let y = bh / 2 - s * (view.cy * ih)

  // Never let the frame run off the edge of the photograph.
  x = Math.min(0, Math.max(bw - s * bw, x))
  y = Math.min(0, Math.max(bh - s * ih, y))

  img.style.transform = `translate3d(${x.toFixed(2)}px, ${y.toFixed(2)}px, 0) scale(${s.toFixed(4)})`
}

export const lerpView = (a, b, t) => ({
  cx: a.cx + (b.cx - a.cx) * t,
  cy: a.cy + (b.cy - a.cy) * t,
  w: a.w + (b.w - a.w) * t,
})

// Slow in, slow out. Used between stops so the travel reads as a camera move
// rather than a jump, and so a fast scroll does not tear through six stages.
export const easeInOut = (t) => (t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2)

export const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

import { useEffect, useLayoutEffect, useRef, useState } from 'react'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import { POWER_PATH } from './data.js'
import { applyView, lerpView, easeInOut, prefersReducedMotion } from './loupe.js'

gsap.registerPlugin(ScrollTrigger)

const LAST = POWER_PATH.length - 1

// Desktop: the section is pinned and one scroll value drives everything —
// the crop, the stage, the readout, the rail. Mobile: the same value, set a
// stop at a time by the reader, because six pinned screens on a phone is a
// trap. There is only ever one progress number.
export default function PowerPath() {
  const section = useRef(null)
  const pin = useRef(null)
  const box = useRef(null)
  const img = useRef(null)
  const clip = useRef(null)
  const [stage, setStage] = useState(0)
  const [travel, setTravel] = useState(0)
  const [stepped, setStepped] = useState(false)
  const progress = useRef({ p: 0 })

  // One place where a progress value becomes a rendered frame.
  const render = (p) => {
    const raw = Math.min(LAST, Math.max(0, p * LAST))
    const i = Math.min(LAST - 1, Math.floor(raw))
    const t = easeInOut(raw - i)
    applyView(img.current, box.current, lerpView(POWER_PATH[i].view, POWER_PATH[i + 1].view, t))
    const active = Math.round(raw)
    setStage((s) => (s === active ? s : active))
    setTravel(raw / LAST)
  }

  useLayoutEffect(() => {
    const mm = gsap.matchMedia()

    mm.add('(min-width: 900px) and (prefers-reduced-motion: no-preference)', () => {
      setStepped(false)
      const st = ScrollTrigger.create({
        trigger: section.current,
        start: 'top top',
        end: 'bottom bottom',
        pin: pin.current,
        pinSpacing: false,
        scrub: 0.35,
        onUpdate: (self) => {
          progress.current.p = self.progress
          render(self.progress)
        },
        onRefresh: () => render(progress.current.p),
      })
      render(progress.current.p)
      return () => st.kill()
    })

    mm.add('(max-width: 899px), (prefers-reduced-motion: reduce)', () => {
      setStepped(true)
      render(progress.current.p)
      const onResize = () => render(progress.current.p)
      window.addEventListener('resize', onResize)
      return () => window.removeEventListener('resize', onResize)
    })

    return () => mm.revert()
  }, [])

  // Stepped mode: tween the same progress value so the travel between two
  // stops is the same camera move it is on the desktop scrub.
  const goTo = (index) => {
    const target = index / LAST
    if (prefersReducedMotion()) {
      progress.current.p = target
      render(target)
      return
    }
    gsap.to(progress.current, {
      p: target,
      duration: 0.9,
      ease: 'power2.inOut',
      overwrite: true,
      onUpdate: () => render(progress.current.p),
    })
  }

  const current = POWER_PATH[stage]
  const live = !!current.live

  // The clip runs only while the escapement and balance are on screen.
  useEffect(() => {
    const v = clip.current
    if (!v) return
    if (live) v.play().catch(() => {})
    else v.pause()
  }, [live])

  return (
    <section
      className="path"
      id="power-path"
      ref={section}
      aria-labelledby="path-title"
      style={stepped ? undefined : { height: `${(POWER_PATH.length + 1) * 100}vh` }}
    >
      <div className="path-pin" ref={pin}>
        <div className="path-inner">
          <header className="path-head">
            <p className="eyebrow">Section 01 — the power path</p>
            <h2 id="path-title" className="path-title">
              Where the energy goes
            </h2>
            <p className="path-lede">
              Seventy-two hours of stored energy, released one escape-wheel tooth at a time, five
