import { chromium } from 'playwright'
const URL = 'http://localhost:4173/'
const tag = process.argv[2] || 'a'
const b = await chromium.launch()
const errs = []

async function shoot(name, width, height, fn) {
  const ctx = await b.newContext({ viewport: { width, height }, deviceScaleFactor: 1 })
  const p = await ctx.newPage()
  p.on('console', (m) => m.type() === 'error' && errs.push(`[${name}] ${m.text()}`))
  p.on('pageerror', (e) => errs.push(`[${name}] pageerror ${e.message}`))
  p.on('requestfailed', (r) => errs.push(`[${name}] 404? ${r.url()} ${r.failure()?.errorText}`))
  await p.goto(URL, { waitUntil: 'networkidle' })
  await p.waitForTimeout(900)
  if (fn) await fn(p)
  await p.screenshot({ path: `_work/shots/${tag}-${name}.png`, fullPage: !fn })
  await ctx.close()
}

// full pages
await shoot('desk-full', 1440, 900)
await shoot('mob-full', 390, 844)

// the pinned traversal, at each stop, captured as viewports
for (const [i, at] of [0, 0.2, 0.4, 0.6, 0.8, 1].entries()) {
  await shoot(`path-${i}`, 1440, 900, async (p) => {
    const sec = await p.$('#power-path')
    const bb = await sec.boundingBox()
    const scrollable = bb.height - 900
    await p.evaluate((y) => window.scrollTo(0, y), bb.y + scrollable * at)
    await p.waitForTimeout(1100)
  })
}

// sections
for (const id of ['stack', 'record', 'finishes', 'atelier', 'reserve']) {
  await shoot(`sec-${id}`, 1440, 900, async (p) => {
    await p.evaluate((i) => document.getElementById(i).scrollIntoView(), id)
    await p.waitForTimeout(900)
  })
  await shoot(`mob-${id}`, 390, 844, async (p) => {
    await p.evaluate((i) => document.getElementById(i).scrollIntoView(), id)
    await p.waitForTimeout(900)
  })
}

await b.close()
console.log(errs.length ? errs.join('\n') : 'no console/network errors')
EOF
